contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount == 1 ether);

        // settle with no guess locked in must revert
        bool settle1Reverted;
        try c.settle() { settle1Reverted = false; } catch { settle1Reverted = true; }

        // locking a guess with exactly 1 ether succeeds
        bool lockReverted;
        bytes32 g = keccak256(abi.encodePacked(amount));
        try c.lockInGuess{value: amount}(g) { lockReverted = false; } catch { lockReverted = true; }

        // settle in the same block (guessed block not yet passed) must still revert
        bool settle2Reverted;
        try c.settle() { settle2Reverted = false; } catch { settle2Reverted = true; }

        assert(settle1Reverted && !lockReverted && settle2Reverted && address(c).balance == 2 ether);
    }

    receive() external payable {}
}

